// Opt-in, per-trial event recorder for the replay viewer. It watches a trial at
// three points: the brain's decisions, the wire as the agent sees it (after any
// fault), and the wire as the services see it (before any fault, where side
// effects land in the sandbox ledger). It never touches randomness or results,
// so a recorded trial behaves exactly like an unrecorded one with the same seed.

import type { FaultEvent } from './chaos/faults';
import type { Decision, Transport } from './target';

type Endpoint = string;

/** A runaway trial (e.g. an endless pagination loop) can make thousands of calls; the timeline keeps the first ones. */
export const MAX_TIMELINE_EVENTS = 1500;

interface Base {
  /** Position in the timeline. */
  i: number;
  /** Milliseconds since the trial started. Wall-clock, so it is not part of the deterministic replay. */
  t: number;
}

export type TrialEvent = Base &
  (
    | { type: 'brain'; step: number; decision: Decision }
    | { type: 'call'; call: number; endpoint: Endpoint; input: Record<string, unknown>; attempt: number; retryOf?: number }
    | { type: 'result'; call: number; endpoint: Endpoint; output: unknown; ms: number; late?: boolean }
    | { type: 'error'; call: number; endpoint: Endpoint; error: string; ms: number; late?: boolean }
    | { type: 'timeout'; call: number; endpoint: Endpoint; afterMs: number; detail: string }
    | { type: 'fault'; call: number; fault: string; kind: string; endpoint: Endpoint; detail: string }
    /** A new ledger entry; `effect` is the singular of the target's effect key (refunds → refund, apiCalls → apiCall). */
    | { type: 'effect'; effect: string; data: unknown }
    | { type: 'outcome'; outcome: string; error?: string; reply?: string; steps: number; durationMs: number; dropped?: number }
  );

type Draft = TrialEvent extends infer E ? (E extends TrialEvent ? Omit<E, 'i' | 't'> : never) : never;

const parse = (raw: string): unknown => {
  try {
    return JSON.parse(raw);
  } catch {
    return raw; // e.g. truncated JSON: show exactly what the agent received
  }
};

export class TrialRecorder {
  readonly events: TrialEvent[] = [];
  private start = performance.now();
  private stopped = false;
  private calls = 0;
  /** The call the agent is currently making, so a fault fired inside it can point back to it. */
  private current = 0;
  private pending = new Map<number, { endpoint: Endpoint; at: number; superseded: boolean }>();
  private attempts = new Map<Endpoint, number>();

  private now = () => performance.now() - this.start;

  /** Events past MAX_TIMELINE_EVENTS, counted instead of kept. */
  private dropped = 0;

  private push(e: Draft) {
    if (this.stopped) return;
    if (this.events.length >= MAX_TIMELINE_EVENTS && e.type !== 'outcome') {
      this.dropped++;
      return;
    }
    if (e.type === 'outcome' && this.dropped) e = { ...e, dropped: this.dropped };
    this.events.push({ i: this.events.length, t: Math.round(this.now()), ...e } as TrialEvent);
  }

  /** Freezes the timeline; anything a wound-down run does afterwards is ignored. */
  stop() {
    this.stopped = true;
  }

  brain(step: number, decision: Decision) {
    this.push({ type: 'brain', step, decision });
  }

  /** For FaultContext.onEvent. */
  fault = (e: FaultEvent) => {
    this.push({ type: 'fault', call: this.current, fault: e.fault, kind: e.kind, endpoint: e.endpoint, detail: e.title });
  };

  outcome(o: { outcome: string; error?: string; reply?: string; steps: number; durationMs: number }) {
    // Calls nobody is waiting on any more: a timed-out request, or the one a hung run was stuck on.
    for (const [call, p] of this.pending) {
      if (p.superseded) continue;
      p.superseded = true;
      const afterMs = Math.round(this.now() - p.at);
      this.push({ type: 'timeout', call, endpoint: p.endpoint, afterMs, detail: `call #${call} still in flight after ~${afterMs}ms when the run ended (${o.outcome})` });
    }
    const { outcome, error, reply, steps } = o;
    this.push({ type: 'outcome', outcome, ...(error ? { error } : {}), ...(reply !== undefined ? { reply } : {}), steps, durationMs: Math.round(o.durationMs) });
  }

  /** Wraps the transport the agent calls (outermost, after fault injection). */
  agentSide<T extends Transport<any>>(transport: T): T {
    const wrapped: Transport = async (endpoint, payload) => {
      const call = ++this.calls;
      const at = this.now();
      // The agent never tells the wire it gave up, but a second call to the same
      // endpoint while the first is still in flight means it timed out and retried.
      const inFlight = [...this.pending].filter(([, p]) => p.endpoint === endpoint && !p.superseded);
      let retryOf: number | undefined;
      for (const [id, p] of inFlight) {
        p.superseded = true;
        retryOf = id;
        const afterMs = Math.round(at - p.at);
        this.push({
          type: 'timeout',
          call: id,
          endpoint,
          afterMs,
          detail: `agent stopped waiting for call #${id} after ~${afterMs}ms; the request is still in flight`,
        });
      }
      const attempt = (this.attempts.get(endpoint) ?? 0) + 1;
      this.attempts.set(endpoint, attempt);
      this.pending.set(call, { endpoint, at, superseded: false });
      this.push({ type: 'call', call, endpoint, input: payload, attempt, ...(retryOf ? { retryOf } : {}) });

      this.current = call;
      const res = transport(endpoint, payload);
      this.current = 0;
      try {
        const raw = await res;
        const p = this.pending.get(call)!;
        this.push({ type: 'result', call, endpoint, output: parse(raw), ms: Math.round(this.now() - at), ...(p.superseded ? { late: true } : {}) });
        return raw;
      } catch (err) {
        const p = this.pending.get(call)!;
        const error = err instanceof Error ? err.message : String(err);
        this.push({ type: 'error', call, endpoint, error, ms: Math.round(this.now() - at), ...(p.superseded ? { late: true } : {}) });
        throw err;
      } finally {
        this.pending.delete(call);
      }
    };
    return wrapped as T;
  }

  /** Wraps the services' transport (innermost, before fault injection) to catch real side effects. */
  serviceSide<T extends Transport<any>>(transport: T, observe: () => Record<string, unknown[]>): T {
    const wrapped: Transport = async (endpoint, payload) => {
      const before = Object.fromEntries(Object.entries(observe()).map(([k, v]) => [k, v.length]));
      try {
        return await transport(endpoint, payload);
      } finally {
        for (const [key, entries] of Object.entries(observe())) {
          const effect = key.replace(/s$/, '');
          for (const d of entries.slice(before[key] ?? 0)) this.push({ type: 'effect', effect, data: typeof d === 'object' && d ? { ...d } : d });
        }
      }
    };
    return wrapped as T;
  }
}

/** The timeline without wall-clock fields: what must be identical across replays of one seed. */
export function stableTimeline(events: TrialEvent[]): unknown[] {
  return events.map(({ t: _t, ...e }) => {
    const { ms: _ms, afterMs: _a, durationMs: _d, detail, ...rest } = e as Record<string, unknown>;
    // Timeout details embed a wall-clock duration; the rest of the detail text is stable.
    return e.type === 'timeout' ? rest : { ...rest, ...(detail !== undefined ? { detail } : {}) };
  });
}
// Trial replay: every trial is reproducible from its seed, so re-running one
// with the recorder on gives its full step-by-step story (brain decisions, tool
// calls, injected faults, retries, side effects, outcome, broken rules).

import { existsSync } from 'node:fs';
import { join, resolve, sep } from 'node:path';
import { getFault } from './chaos/faults';
import { runTrial, type TrialObservation } from './harness';
import { compileRules } from './invariants';
import type { TrialEvent } from './recorder';
import { loadTarget, resolveTargetDir, type BulwarkTarget } from './target';

export interface ReplayResult {
  target: string;
  fault: string;
  seed: number;
  /** Where the code came from: the original target dir, or a loop workspace (patched code). */
  source: string;
  observation: Omit<TrialObservation, 'timeline'>;
  broken: { rule: string; how: string; detail?: string }[];
  timeline: TrialEvent[];
}

/** Same settings the dashboard and the loop use, so a replay matches the square that was clicked. */
export const REPLAY_DEFAULTS = { brain: 'simulated' as const, deadlineMs: 5000, maxSteps: 50 };

const SAFE = /^[\w-]{1,128}$/;

/**
 * Turns untrusted query parameters into a target directory, or throws.
 * - `run` + `ws`: a loop workspace, `.bulwark/runs/<run>/ws/<ws>` (e.g. ws = "timeout-after-commit-accepted").
 * - `target`: a directory under `targets/` ("refundbot" or "targets/refundbot").
 * Only plain names are accepted, so nothing can climb out of those roots.
 */
export function resolveReplayDir(params: { target?: string | null; run?: string | null; ws?: string | null }, stateDir = '.bulwark'): string {
  const { run, ws } = params;
  if (run || ws) {
    if (!run || !ws || !SAFE.test(run) || !SAFE.test(ws)) throw new Error('run and ws must both be plain names');
    const root = resolve(stateDir, 'runs');
    const dir = resolve(root, run, 'ws', ws);
    if (!dir.startsWith(root + sep)) throw new Error('workspace outside the runs directory');
    if (!existsSync(join(dir, 'bulwark.target.ts'))) throw new Error(`no workspace ${run}/${ws}`);
    return dir;
  }
  return resolveTargetDir(params.target);
}

export async function replayTrial(args: {
  target: BulwarkTarget;
  fault: string;
  seed: number;
  source?: string;
  deadlineMs?: number;
  maxSteps?: number;
}): Promise<ReplayResult> {
  const fault = args.fault === 'baseline' ? undefined : getFault(args.fault, args.target);
  if (!Number.isInteger(args.seed) || args.seed < 0 || args.seed > 0xffffffff) throw new Error('seed must be a 32-bit unsigned integer');
  const { compiled, uncompiled } = compileRules(args.target.rules, args.target.checks);
  if (uncompiled.length) throw new Error(`could not compile rules: ${uncompiled.join(' | ')}`);

  const obs = await runTrial({
    ...REPLAY_DEFAULTS,
    ...(args.deadlineMs ? { deadlineMs: args.deadlineMs } : {}),
    ...(args.maxSteps ? { maxSteps: args.maxSteps } : {}),
    target: args.target,
    fault,
    seed: args.seed,
    traced: false,
    record: true,
  });
  const { timeline = [], ...observation } = obs;
  const broken = compiled.flatMap(({ rule, how, check }) => {
    const res = check(obs);
    return res.ok ? [] : [{ rule, how, detail: res.detail }];
  });
  return { target: args.target.name, fault: fault?.id ?? 'baseline', seed: args.seed, source: args.source ?? args.target.name, observation, broken, timeline };
}

/** For the API: validates the parameters, loads the right code, replays. */
export async function replayFromParams(params: URLSearchParams): Promise<ReplayResult> {
  const fault = params.get('fault') ?? '';
  const seedStr = params.get('seed') ?? '';
  if (!/^\d{1,10}$/.test(seedStr)) throw new Error('seed must be a non-negative integer');
  const dir = resolveReplayDir({ target: params.get('target'), run: params.get('run'), ws: params.get('ws') });
  const run = params.get('run');
  const source = run ? `.bulwark/runs/${run}/ws/${params.get('ws')}` : `targets/${dir.split(sep).pop()}`;
  return replayTrial({ target: await loadTarget(dir), fault, seed: Number(seedStr), source });
}

const short = (v: unknown, n = 140) => {
  const s = typeof v === 'string' ? JSON.stringify(v) : JSON.stringify(v) ?? String(v);
  return s.length > n ? s.slice(0, n - 1) + '…' : s;
};

/** One line per event, for the terminal. */
export function describeEvent(e: TrialEvent): string {
  switch (e.type) {
    case 'brain':
      return e.decision.type === 'tool'
        ? `brain    step ${e.step}: call ${e.decision.name} ${short(e.decision.input)}`
        : `brain    step ${e.step}: final reply ${short(e.decision.reply)}`;
    case 'call':
      return `tool  →  #${e.call} ${e.endpoint} ${short(e.input)}${e.retryOf ? `  (RETRY of #${e.retryOf}, attempt ${e.attempt})` : ''}`;
    case 'result':
      return `tool  ←  #${e.call} ${e.endpoint} ${short(e.output)} (${e.ms}ms)${e.late ? '  LATE: agent already gave up' : ''}`;
    case 'error':
      return `tool  ✗  #${e.call} ${e.endpoint} ERROR ${e.error} (${e.ms}ms)${e.late ? '  (late)' : ''}`;
    case 'timeout':
      return `timeout  #${e.call} ${e.endpoint}: ${e.detail}`;
    case 'fault':
      return `FAULT    ${e.fault} on #${e.call} ${e.endpoint}: ${e.detail}`;
    case 'effect':
      return `effect   ${e.effect}: ${short(e.data)}`;
    case 'outcome':
      return `outcome  ${e.outcome.toUpperCase()} after ${e.steps} steps, ${e.durationMs}ms${e.error ? ` · error: ${e.error}` : ''}${e.reply ? ` · reply: ${short(e.reply)}` : ''}${e.dropped ? ` · ${e.dropped} later events not kept` : ''}`;
  }
}
// npm run replay -- --fault timeout-after-commit --seed <n> [--target refundbot] [--run <runId> --ws <label>] [--json]
//
// Re-runs one trial from its seed with the recorder on and prints its timeline.

import { parseArgs } from 'node:util';
import { describeEvent, replayFromParams } from './replay';

async function main() {
  const { values } = parseArgs({
    options: {
      fault: { type: 'string', default: 'timeout-after-commit' },
      seed: { type: 'string' },
      target: { type: 'string' },
      run: { type: 'string' },
      ws: { type: 'string' },
      json: { type: 'boolean', default: false },
    },
  });
  if (!values.seed) throw new Error('--seed is required (find one in a scorecard\'s "replayable failures")');
  const params = new URLSearchParams();
  for (const k of ['fault', 'seed', 'target', 'run', 'ws'] as const) if (values[k]) params.set(k, values[k]!);

  const r = await replayFromParams(params);
  if (values.json) return console.log(JSON.stringify(r, null, 2));

  console.log(`Replay ${r.fault} · seed ${r.seed} · ${r.source}\n`);
  for (const e of r.timeline) console.log(`${String(e.t).padStart(6)}ms  ${describeEvent(e)}`);
  console.log('');
  if (r.broken.length === 0) console.log('✓ every rule held');
  for (const b of r.broken) console.log(`✗ ${b.rule}\n    ${b.detail ?? ''}\n    how it's checked: ${b.how}`);
}

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});
// Local site: npm run dashboard → http://localhost:5317 (landing page), /app (dashboard)
// Streams chaos experiments to the browser as trials finish (Server-Sent Events).

import './env';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createServer, type ServerResponse } from 'node:http';
import { relative } from 'node:path';
import { faultsFor, getFault, type Fault } from './chaos/faults';
import { parseSlo } from './judge/slo';
import { parseTournament } from './judge/tournament';
import { runLoop } from './loop/orchestrator';
import { replayFromParams } from './replay';
import { runExperiment } from './scorecard';
import { defaultModel, llmLabel, llmProvider } from './llm';
import { listTargets, loadTarget, resolveTargetDir, type BulwarkTarget } from './target';
import { initTracing } from './tracing';

const PORT = Number(process.env.PORT ?? 5317);
const PAGES: Record<string, URL> = {
  '/': new URL('./dashboard/landing.html', import.meta.url),
  '/app': new URL('./dashboard/index.html', import.meta.url),
};

function send(res: ServerResponse, event: string, data: unknown) {
  res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

// ?target=researchbot (default refundbot): only directories under targets/ with a bulwark.target.ts.
const loaded = new Map<string, Promise<BulwarkTarget>>();
function targetFrom(params: URLSearchParams): Promise<BulwarkTarget> {
  let dir: string;
  try {
    dir = resolveTargetDir(params.get('target'));
  } catch (err) {
    return Promise.reject(err);
  }
  if (!loaded.has(dir)) loaded.set(dir, loadTarget(dir));
  return loaded.get(dir)!;
}

async function streamRun(res: ServerResponse, params: URLSearchParams) {
  res.writeHead(200, { 'content-type': 'text/event-stream', 'cache-control': 'no-cache', connection: 'keep-alive' });
  const faultParam = params.get('fault') ?? 'all';
  const target = await targetFrom(params);
  const faults: (Fault | undefined)[] = faultParam === 'all' ? [undefined, ...faultsFor(target)] : [undefined, getFault(faultParam, target)];
  const opts = {
    trials: Math.min(200, Math.max(1, Number(params.get('trials') ?? 20))),
    seed: Number(params.get('seed') ?? 42),
    brain: 'simulated' as const,
    deadlineMs: 5000,
    maxSteps: 50,
    sessionId: `chaos-${new Date().toISOString().replace(/[:.]/g, '-')}`,
  };

  // Experiments run concurrently so the whole board fills in at once.
  await Promise.all(
    faults.map(async (fault) => {
      const id = fault?.id ?? 'baseline';
      send(res, 'experiment-start', { fault: id, trials: opts.trials });
      const result = await runExperiment(target, fault, {
        ...opts,
        onTrial: ({ index, obs, broken }) =>
          send(res, 'trial', {
            fault: id,
            index,
            outcome: obs.outcome,
            passed: broken.length === 0,
            broken,
            seed: obs.seed,
            durationMs: Math.round(obs.durationMs),
            steps: obs.steps,
            refunds: (obs.refunds ?? []).map((r) => r.amount),
            error: obs.error,
          }),
      });
      send(res, 'experiment-done', result);
    }),
  );
  send(res, 'done', {});
  res.end();
}

let loopRunning = false;

async function streamLoop(res: ServerResponse, params: URLSearchParams) {
  res.writeHead(200, { 'content-type': 'text/event-stream', 'cache-control': 'no-cache', connection: 'keep-alive' });
  if (loopRunning) {
    send(res, 'loop-error', { message: 'A Bulwark loop is already running. Wait for it to finish.' });
    return res.end();
  }
  loopRunning = true;
  try {
    // Optional: a reliability target (e.g. slo=0.95) and a fix tournament (e.g. tournament=playbook,playbook-strong).
    const slo = params.get('slo') ? parseSlo(params.get('slo')!) : undefined;
    const tournament = params.get('tournament') ? parseTournament(params.get('tournament')!) : undefined;
    await runLoop(
      {
        targetDir: relative(process.cwd(), resolveTargetDir(params.get('target'))),
        // neatlogs read-back wait per fault: short by default so the live demo stays snappy (wait=0 to skip).
        readbackWaitMs: Math.min(60_000, Math.max(0, Number(params.get('wait') ?? process.env.BULWARK_NEATLOGS_WAIT_MS ?? 5000))),
        ...(slo ? { slo } : {}),
        ...(tournament ? { tournament } : {}),
        memory: params.get('memory') === '1',
        redTrials: Math.min(100, Math.max(5, Number(params.get('trials') ?? 20))),
        seed: Number(params.get('seed') ?? 42),
      },
      (e) => send(res, 'loop', e.type === 'run-done' ? { ...e, summary: { ...e.summary, finalFiles: undefined } } : e),
    );
  } catch (err) {
    send(res, 'loop-error', { message: err instanceof Error ? err.message : String(err) });
  } finally {
    loopRunning = false;
    res.end();
  }
}

const ARTIFACT_TYPES: Record<string, string> = {
  md: 'text/markdown; charset=utf-8',
  patch: 'text/plain; charset=utf-8',
  json: 'application/json',
  svg: 'image/svg+xml',
};

function serveArtifact(res: ServerResponse, params: URLSearchParams) {
  const run = params.get('run') ?? '';
  const file = params.get('file') ?? '';
  const ext = file.split('.').pop() ?? '';
  const path = join('.bulwark', 'runs', run, file);
  if (!/^[\w-]+$/.test(run) || !/^[\w.-]+$/.test(file) || !(ext in ARTIFACT_TYPES) || !existsSync(path)) {
    return res.writeHead(404).end('not found');
  }
  res.writeHead(200, { 'content-type': ARTIFACT_TYPES[ext] });
  res.end(readFileSync(path));
}

async function main() {
  const exporting = await initTracing('bulwark-dashboard');

  createServer((req, res) => {
    const url = new URL(req.url ?? '/', `http://localhost:${PORT}`);
    if (url.pathname in PAGES) {
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      res.end(readFileSync(PAGES[url.pathname]));
    } else if (url.pathname === '/api/meta') {
      targetFrom(url.searchParams).then(
        (target) =>
          res.writeHead(200, { 'content-type': 'application/json' }).end(
            JSON.stringify({
              target: target.name,
              targets: listTargets(),
              rules: target.rules,
              // Dollars at risk is only shown for targets with a risk model.
              risk: !!target.risk,
              neatlogs: exporting,
              fixer: llmProvider() ? `${defaultModel('fixer')} via ${llmLabel()} + playbook` : 'playbook (add an LLM key for Claude)',
              faults: [
                { id: 'baseline', title: 'No fault injected', hypothesis: 'The agent works when nothing breaks.' },
                ...faultsFor(target).map(({ id, title, hypothesis }) => ({ id, title, hypothesis })),
              ],
            }),
          ),
        (err) => res.writeHead(400, { 'content-type': 'application/json' }).end(JSON.stringify({ error: err instanceof Error ? err.message : String(err) })),
      );
    } else if (url.pathname === '/api/loop') {
      streamLoop(res, url.searchParams);
    } else if (url.pathname === '/api/replay') {
      replayFromParams(url.searchParams).then(
        (r) => res.writeHead(200, { 'content-type': 'application/json' }).end(JSON.stringify(r)),
        (err) => res.writeHead(400, { 'content-type': 'application/json' }).end(JSON.stringify({ error: err instanceof Error ? err.message : String(err) })),
      );
    } else if (url.pathname === '/api/artifact') {
      serveArtifact(res, url.searchParams);
    } else if (url.pathname === '/theme.css') {
      res.writeHead(200, { 'content-type': 'text/css; charset=utf-8', 'cache-control': 'no-cache' });
      res.end(readFileSync(new URL('./dashboard/theme.css', import.meta.url)));
    } else if (url.pathname === '/badge.svg') {
      if (!existsSync('.bulwark/badge.svg')) return res.writeHead(404).end('no badge yet');
      res.writeHead(200, { 'content-type': 'image/svg+xml', 'cache-control': 'no-cache' });
      res.end(readFileSync('.bulwark/badge.svg'));
    } else if (url.pathname === '/api/run') {
      streamRun(res, url.searchParams).catch((err) => {
        send(res, 'error', { message: err instanceof Error ? err.message : String(err) });
        res.end();
      });
    } else {
      res.writeHead(404).end('not found');
    }
  }).listen(PORT, () => {
    console.log(`Bulwark dashboard → http://localhost:${PORT}  (neatlogs ${exporting ? 'exporting' : 'local only'})`);
  });
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
// Guard: every accepted fix ships with a chaos regression test, and the test is
// itself proven: it must fail on the un-fixed code and pass on the fixed code.
// A test that passes either way protects nothing.

import { getFault } from './chaos/faults';
import { runExperiment, type ExperimentOptions, type ExperimentResult } from './scorecard';
import type { BulwarkTarget } from './target';
import type { Files } from './workspace';

export interface ChaosSpec {
  fault: string;
  trials: number;
  seed: number;
  strategy: string;
  createdBy: 'bulwark';
}

export const specPath = (fault: string) => `chaos-tests/${fault}.json`;

export function withSpec(files: Files, spec: ChaosSpec): Files {
  return { ...files, [specPath(spec.fault)]: JSON.stringify(spec, null, 2) + '\n' };
}

export interface MutationCheck {
  ok: boolean;
  unfixed: ExperimentResult;
  fixed: ExperimentResult;
}

export async function mutationCheck(
  spec: ChaosSpec,
  unfixed: BulwarkTarget,
  fixed: BulwarkTarget,
  base: ExperimentOptions,
): Promise<MutationCheck> {
  const opts = { ...base, trials: spec.trials, seed: spec.seed, onTrial: undefined };
  const fault = getFault(spec.fault, unfixed);
  const [u, f] = await Promise.all([runExperiment(unfixed, fault, opts), runExperiment(fixed, fault, opts)]);
  return { ok: u.passed < u.trials && f.passed === f.trials, unfixed: u, fixed: f };
}

// Reads traces back from neatlogs, so Blue diagnoses a failure from what
// neatlogs actually recorded (spans, errors, and neatlogs' own detections), not
// only from Bulwark's local observation. Best-effort: traces take a while to
// finalize, and when one isn't ready in time Blue falls back to local evidence.
// See docs/NEATLOGS.md for measured finalization times.

const ENDPOINT = () => (process.env.NEATLOGS_ENDPOINT || 'https://ingest.neatlogs.com').replace(/\/$/, '');

export interface NeatlogsTrace {
  _id: string;
  name?: string;
  status?: string;
  finalizationStatus?: string;
  hasError?: boolean | number;
  spans?: NeatlogsSpan[];
  detections?: unknown[];
  traceDetections?: unknown[];
  [key: string]: unknown;
}

export interface NeatlogsSpan {
  span_id?: string;
  parent_span_id?: string;
  node_type?: string;
  node_name?: string;
  status?: string;
  createdAt?: string;
  detections?: unknown[];
  span_metadata?: Record<string, unknown>;
  data?: Record<string, unknown>;
}

export type Fetcher = (url: string, init: { headers: Record<string, string> }) => Promise<{ status: number; json(): Promise<unknown> }>;

/**
 * read: finalized with spans. pending: neatlogs hasn't finalized it (202, or 404 while the
 * trace isn't visible yet) within the wait budget. unavailable: no key, no trace id, auth
 * failure, a terminal ingestion failure (409), or reading disabled.
 */
export type ReadStatus = 'read' | 'pending' | 'unavailable';

export interface ReadResult {
  status: ReadStatus;
  trace?: NeatlogsTrace;
  /** Last HTTP status seen (0 = network error, undefined = never asked). */
  http?: number;
  /** neatlogs' finalizationStatus / ingestion stage on the last pending response. */
  stage?: string;
  reason?: string;
  waitedMs: number;
}

/**
 * Polls GET /api/traces/v3/<id> until the trace is finalized with spans, or the wait budget runs out.
 * Mirrors the neatlogs SDK's own doctor read-back: 202 and 404 mean "not ready yet, keep polling",
 * 401/403 mean the key was rejected, 409 is a terminal ingestion failure.
 */
export async function readTrace(traceId: string | undefined, opts: { waitMs?: number; pollMs?: number; fetcher?: Fetcher } = {}): Promise<ReadResult> {
  const started = Date.now();
  const key = process.env.NEATLOGS_API_KEY;
  if (!key) return { status: 'unavailable', reason: 'NEATLOGS_API_KEY not set', waitedMs: 0 };
  if (!traceId) return { status: 'unavailable', reason: 'no traced failing trial', waitedMs: 0 };
  const fetcher = opts.fetcher ?? (fetch as unknown as Fetcher);
  const deadline = started + Math.max(0, opts.waitMs ?? 20_000);
  let http: number | undefined;
  let stage: string | undefined;
  while (true) {
    try {
      const res = await fetcher(`${ENDPOINT()}/api/traces/v3/${encodeURIComponent(traceId)}`, { headers: { 'x-api-key': key } });
      http = res.status;
      if (res.status === 401 || res.status === 403) return { status: 'unavailable', http, reason: 'neatlogs rejected the API key', waitedMs: Date.now() - started };
      const body = (await res.json().catch(() => ({}))) as NeatlogsTrace & { ingestionDiagnostics?: { stage?: string } };
      if (res.status === 409) return { status: 'unavailable', http, reason: `neatlogs ingestion failed (${body.finalizationStatus ?? 'terminal'})`, waitedMs: Date.now() - started };
      if (res.status === 200 && body.spans?.length) return { status: 'read', trace: body, http, waitedMs: Date.now() - started };
      stage = body.finalizationStatus ?? body.ingestionDiagnostics?.stage ?? (res.status === 404 ? 'not visible yet' : stage);
    } catch {
      http = 0; // network hiccup: keep polling until the deadline
    }
    if (Date.now() >= deadline) return { status: 'pending', http, stage, reason: `not finalized within ${Math.round((deadline - started) / 1000)}s`, waitedMs: Date.now() - started };
    await new Promise((r) => setTimeout(r, Math.min(opts.pollMs ?? 2000, Math.max(0, deadline - Date.now()))));
  }
}

const clip = (v: unknown, n: number) => {
  const s = typeof v === 'string' ? v : JSON.stringify(v);
  return s && s.length > n ? `${s.slice(0, n)}…` : s;
};

/** Every detection in the trace: trace-level plus per-span. */
export function traceDetections(trace: NeatlogsTrace): unknown[] {
  return [...(trace.detections ?? []), ...(trace.traceDetections ?? []), ...(trace.spans ?? []).flatMap((s) => s.detections ?? [])];
}

/**
 * The spans of one trial inside a bigger trace. Bulwark's traced trials are `bulwark.trial`
 * spans nested in a phase trace (e.g. "2 red: attack scorecard BEFORE", which holds every fault's
 * sample trials), so the read-back is narrowed to the trial with this fault and seed and its descendants.
 */
export function focusTrial(trace: NeatlogsTrace, focus: { fault?: string; seed?: number }): NeatlogsSpan[] {
  const spans = trace.spans ?? [];
  const meta = (s: NeatlogsSpan) => ({ ...(s.span_metadata ?? {}), ...(s.data ?? {}) }) as Record<string, unknown>;
  const root = spans.find((s) => {
    if (s.node_name !== 'bulwark.trial') return false;
    const m = meta(s);
    return (focus.seed === undefined || String(m.seed) === String(focus.seed)) && (focus.fault === undefined || m.fault === undefined || m.fault === focus.fault);
  });
  if (!root?.span_id) return spans;
  const keep = new Set([root.span_id]);
  // Children can be listed before parents; repeat until no new descendants turn up.
  for (let grew = true; grew; ) {
    grew = false;
    for (const s of spans) {
      if (s.span_id && s.parent_span_id && keep.has(s.parent_span_id) && !keep.has(s.span_id)) {
        keep.add(s.span_id);
        grew = true;
      }
    }
  }
  return spans.filter((s) => s.span_id && keep.has(s.span_id));
}

/** A compact, model-friendly digest of a trace: detections first, then the span timeline. */
export function summarizeTrace(trace: NeatlogsTrace, opts: { maxSpans?: number; focus?: { fault?: string; seed?: number } } = {}): string {
  const all = trace.spans ?? [];
  const picked = opts.focus ? focusTrial(trace, opts.focus) : all;
  const spans = [...picked].sort((a, b) => String(a.createdAt ?? '').localeCompare(String(b.createdAt ?? '')));
  const detections = [...(trace.detections ?? []), ...(trace.traceDetections ?? []), ...spans.flatMap((s) => s.detections ?? [])];
  const scope = picked.length < all.length ? ` (${spans.length} of ${all.length} spans: the trial with seed ${opts.focus?.seed})` : `: ${spans.length} spans`;
  const lines = [`neatlogs trace ${trace._id} "${trace.name ?? ''}"${scope}${trace.hasError ? ', has errors' : ''}`];
  for (const d of detections.slice(0, 8)) lines.push(`neatlogs detection: ${clip(d, 300)}`);
  for (const s of spans.slice(0, opts.maxSpans ?? 40)) {
    const d = s.data ?? {};
    const tool = (d.tool_name as string) || (s.span_metadata?.tool_name as string) || (s.node_type === 'tool_call' ? s.node_name : '');
    const bits = [
      `${s.node_type ?? ''} ${s.node_name ?? ''}`.trim(),
      s.status ? `status=${s.status}` : '',
      typeof d.duration_ms === 'number' ? `${Math.round(d.duration_ms)}ms` : '',
      tool && d.input_value ? `input=${clip(d.input_value, 120)}` : '',
      d.output_value ? `output=${clip(d.output_value, 160)}` : '',
      d.error_message ? `error=${d.error_type ?? ''}: ${clip(d.error_message, 160)}` : '',
    ];
    lines.push(`- ${bits.filter(Boolean).join(' ')}`);
  }
  return lines.join('\n');
}
// Observe step: before Blue proposes a fix, read a failing trial's trace back
// from neatlogs and hand Blue what neatlogs recorded. Bounded by a wait budget,
// never throws, and degrades to "unavailable" without a key.
//
// neatlogs finalizes traces asynchronously and not always within a run (see
// docs/NEATLOGS.md), so candidates are tried oldest first: a failing trial
// from the previous run on the same code (trials replay deterministically from
// their seed, so it is the same failure, and it has had minutes to finalize),
// then this run's BEFORE scorecard, then the Judge's baseline, then a traced
// re-run of one failing seed.

import { focusTrial, readTrace, summarizeTrace, type Fetcher, type ReadResult, type ReadStatus } from './neatlogs';

export interface ObserveCandidate {
  seed: number;
  traceId?: string;
  /** Where the failing trial came from. */
  source: 'previous' | 'before' | 'judge' | 'rerun';
}

export interface ObserveRecord {
  fault: string;
  traceId?: string;
  seed?: number;
  source?: ObserveCandidate['source'];
  status: ReadStatus;
  /** Spans of the failing trial (the trace is narrowed to it). */
  spans: number;
  detections: number;
  waitedMs: number;
  reason?: string;
  stage?: string;
  /** Set when the trace was still pending for Blue but had finalized by the end of the run. */
  late?: boolean;
}

export interface ObserveOptions {
  fault: string;
  /** Failing trials, best first. */
  candidates: ObserveCandidate[];
  /** Re-runs one failing seed traced and returns its trace id (trials replay deterministically from a seed). */
  rerun?: (seed: number) => Promise<string | undefined>;
  waitMs: number;
  pollMs?: number;
  fetcher?: Fetcher;
  /** Reads already made in this run, by trace id; phase traces hold every fault's trials, so one read serves many faults. */
  cache?: Map<string, ReadResult>;
}

const SOURCE_LABEL: Record<ObserveCandidate['source'], string> = {
  previous: "previous run's BEFORE scorecard (same code, same seed)",
  before: 'BEFORE scorecard',
  judge: "Judge's baseline",
  rerun: 'traced re-run',
};

/** Turns a successful read into the record's span/detection counts and Blue's evidence. */
function digest(record: ObserveRecord, res: ReadResult, fault: string): string | undefined {
  if (res.status !== 'read' || !res.trace || record.seed === undefined) return undefined;
  const focus = { fault, seed: record.seed };
  const spans = focusTrial(res.trace, focus);
  record.spans = spans.length;
  record.detections = [...(res.trace.detections ?? []), ...(res.trace.traceDetections ?? []), ...spans.flatMap((s) => s.detections ?? [])].length;
  return summarizeTrace(res.trace, { focus });
}

export async function observeFailure(o: ObserveOptions): Promise<{ record: ObserveRecord; evidence?: string }> {
  const base = { fault: o.fault, spans: 0, detections: 0, waitedMs: 0 };
  if (o.waitMs <= 0) return { record: { ...base, status: 'unavailable', reason: 'neatlogs read-back disabled (wait 0)' } };
  if (!process.env.NEATLOGS_API_KEY) return { record: { ...base, status: 'unavailable', reason: 'NEATLOGS_API_KEY not set' } };

  const seen = new Set<string>();
  const traced = o.candidates.filter((c) => c.traceId && !seen.has(c.traceId) && seen.add(c.traceId));
  if (!traced.some((c) => c.source !== 'previous') && o.rerun && o.candidates.length) {
    const seed = o.candidates.find((c) => c.source !== 'previous')?.seed ?? o.candidates[0].seed;
    try {
      const traceId = await o.rerun(seed);
      if (traceId) traced.push({ seed, traceId, source: 'rerun' });
    } catch {
      // no trace to read from the re-run
    }
  }
  if (!traced.length) return { record: { ...base, status: 'unavailable', reason: 'no traced failing trial' } };

  const started = Date.now();
  let best: ObserveRecord | undefined;
  let fullWaitUsed = false;
  for (const c of traced) {
    const cached = o.cache?.get(c.traceId!);
    // Older traces either finalized long ago or never will: one check. The first trace from this run
    // gets the wait budget; a trace that was already pending earlier in the run gets one re-check.
    const wait = cached || c.source === 'previous' || fullWaitUsed ? 0 : Math.max(0, o.waitMs - (Date.now() - started));
    if (wait > 0) fullWaitUsed = true;
    const res = cached?.status === 'read' ? cached : await readTrace(c.traceId, { waitMs: wait, pollMs: o.pollMs, fetcher: o.fetcher });
    o.cache?.set(c.traceId!, res);
    const record: ObserveRecord = {
      ...base,
      traceId: c.traceId,
      seed: c.seed,
      source: c.source,
      status: res.status,
      waitedMs: Date.now() - started,
      ...(res.reason ? { reason: res.reason } : {}),
      ...(res.stage ? { stage: res.stage } : {}),
    };
    const evidence = digest(record, res, o.fault);
    if (evidence) return { record, evidence };
    // Report the most useful miss: this run's pending trace over an old or unavailable one.
    const rank = (r: ObserveRecord) => (r.status === 'pending' ? 2 : 0) + (r.source === 'previous' ? 0 : 1);
    if (!best || rank(record) > rank(best)) best = record;
  }
  return { record: best! };
}

/**
 * End of run: one more look at traces that were still pending when Blue needed them. A trace that
 * has finalized since is recorded as a late read for the postmortem (Blue still used local evidence).
 */
export async function recheckPending(records: (ObserveRecord | undefined)[], opts: { fetcher?: Fetcher; cache?: Map<string, ReadResult> } = {}): Promise<number> {
  let late = 0;
  for (const r of records) {
    if (r?.status !== 'pending' || !r.traceId) continue;
    const res = opts.cache?.get(r.traceId)?.status === 'read' ? opts.cache.get(r.traceId)! : await readTrace(r.traceId, { waitMs: 0, fetcher: opts.fetcher });
    opts.cache?.set(r.traceId, res);
    if (res.status !== 'read') {
      if (res.status === 'unavailable' && res.reason) r.reason = `${r.reason ?? 'pending'}; at end of run: ${res.reason}`;
      continue;
    }
    r.status = 'read';
    r.late = true;
    digest(r, res, r.fault);
    late++;
  }
  return late;
}

/** The postmortem / CLI line for one observe step. */
export function describeObserve(r: ObserveRecord): string {
  const from = r.source ? `; failing trial seed ${r.seed} from the ${SOURCE_LABEL[r.source]}` : '';
  if (r.status === 'read' && r.late) return `neatlogs trace ${r.traceId} finalized only after Blue ran (${r.spans} spans, ${r.detections} detections${from}); Blue used local evidence.`;
  if (r.status === 'read') return `Diagnosed from neatlogs trace ${r.traceId} (${r.spans} spans, ${r.detections} detections${from}).`;
  if (r.status === 'pending') return `neatlogs trace ${r.traceId} not finalized in time (${r.reason ?? 'pending'}${r.stage ? `, last state: ${r.stage}` : ''}); used local evidence.`;
  return `neatlogs read-back unavailable (${r.reason ?? 'unknown'}${r.traceId ? `, trace ${r.traceId}` : ''}); used local evidence.`;
}
