      for (const c of row.changes) lines.push(`        ${''.padEnd(col - 2)}   ${'before' in c ? clip(c.before, 30) : '∅'} → ${'after' in c ? clip(c.after, 50) : '∅'}  (${c.path})`);
    }
  });
  return lines.join('\n');
}

